function prettyTime() {
  const d = new Date(Date.now() + 3 * 60 * 60 * 1000);
  const y = d.getUTCFullYear();
  const m = String(d.getUTCMonth() + 1).padStart(2, '0');
  const day = String(d.getUTCDate()).padStart(2, '0');
  const h = String(d.getUTCHours()).padStart(2, '0');
  const min = String(d.getUTCMinutes()).padStart(2, '0');
  const s = String(d.getUTCSeconds()).padStart(2, '0');
  return `${y}-${m}-${day}  ${h}:${min}Рј ${s}СЃ`;
}

const input = $input.first().json || {};
const body = input.body || input;
const cb = body.callback_query;
const state = $getWorkflowStaticData('global');

if (!state.mode) state.mode = 'ACTIVE';
state.venue = 'FUTURES_PAPER';
if (typeof state.paused !== 'boolean') state.paused = false;
if (!state.position) state.position = { side: 'FLAT', entry: 0, qty: 0 };
if (!state.stats) state.stats = { trades: 0, wins: 0, losses: 0, pnl: 0, errors: 0, lastError: '' };

if (!cb) return [{ json: { callbackId: '', text: 'No callback_query received' } }];

const data = cb.data || '';
let text = '';

if (data === 'PAUSE') { state.paused = true; text = 'вЏёпёЏ Futures bot paused'; }
else if (data === 'RESUME') { state.paused = false; text = 'в–¶пёЏ Futures bot resumed'; }
else if (data === 'MODE_SAFE') { state.mode = 'SAFE'; text = 'рџ›ЎпёЏ Mode SAFE'; }
else if (data === 'MODE_ACTIVE') { state.mode = 'ACTIVE'; text = 'вљ™пёЏ Mode ACTIVE'; }
else if (data === 'MODE_AGGRESSIVE') { state.mode = 'AGGRESSIVE'; text = 'рџ”Ґ Mode AGGRESSIVE'; }
else if (data === 'RESET_STATS') { state.stats = { trades: 0, wins: 0, losses: 0, pnl: 0, errors: 0, lastError: '' }; state.position = { side: 'FLAT', entry: 0, qty: 0 }; text = 'в™»пёЏ Stats and internal position reset'; }
else if (data === 'LAST_ERROR') { text = `рџ§ѕ LAST ERROR\n\nErrors: ${state.stats.errors || 0}\nLast Error: ${state.stats.lastError || 'No stored error'}`; }
else if (data === 'BALANCE') { text = `рџ’° INTERNAL FUTURES PAPER STATUS\n\nPosition: ${state.position.side}\nQty: ${state.position.qty || 0}\nEntry: ${state.position.entry || 0}\nPnL total: $${state.stats.pnl || 0}`; }
else if (data === 'STATUS') { text = `рџ“Љ FUTURES PAPER STATUS\n\nPosition: ${state.position.side}\nEntry: ${state.position.entry || 0}\nQty: ${state.position.qty || 0}\nSL: ${state.position.stopLoss || 'N/A'}\nTP: ${state.position.takeProfit || 'N/A'}\nAuto Close: ${state.position.closeAt || 'N/A'}\nMode: ${state.mode}\nVenue: FUTURES_PAPER\nPaused: ${state.paused}\nTrades: ${state.stats.trades || 0}\nPnL: $${state.stats.pnl || 0}\nErrors: ${state.stats.errors || 0}`; }
else { text = 'Unknown command: ' + data; }

return [{
  json: {
    callbackId: cb.id || '',
    text:
`рџ¤– Futures Bot Command

Command: ${data}
${text}

Mode: ${state.mode}
Venue: FUTURES_PAPER
Paused: ${state.paused}
Time: ${prettyTime()}`
  }
}];

